// pages/users/Etinterface/[id].js

"use client";
import { useRouter } from "next/router";

export default function EtudiantInterface() {
  const router = useRouter();
  const { id, data } = router.query;

  // Convertir les données JSON en objet
  const etudiantData = data ? JSON.parse(data) : null;

  if (!etudiantData) {
    return <p>Chargement...</p>;
  }

  const { etudiant, groupe } = etudiantData;

  return (
    <div className="p-8 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold mb-4">Informations de l'étudiant</h1>
      <div className="bg-white p-6 rounded-lg shadow-md">
        <p><strong>Nom:</strong> {etudiant.nom}</p>
        <p><strong>Prénom:</strong> {etudiant.prenom}</p>
        <p><strong>Email:</strong> {etudiant.email}</p>
        <p><strong>Année:</strong> {etudiant.annee}</p>
        <p><strong>Classe:</strong> {etudiant.classe}</p>
        <p><strong>Filière:</strong> {etudiant.filiere}</p>

        <h2 className="text-xl font-bold mt-6 mb-2">Groupe</h2>
        <p><strong>Nom du groupe:</strong> {groupe.nomGroupe}</p>

        <h2 className="text-xl font-bold mt-6 mb-2">Tuteur</h2>
        <p><strong>Nom du tuteur:</strong> {groupe.tuteur?.nomTuteur}</p>

        <h2 className="text-xl font-bold mt-6 mb-2">Sujet</h2>
        <p><strong>Titre du sujet:</strong> {groupe.sujet?.titreSujet}</p>

        <h2 className="text-xl font-bold mt-6 mb-2">Autres étudiants du groupe</h2>
        <ul>
          {groupe.etudiants?.map((etudiant) => (
            <li key={etudiant.idEtudiant}>{etudiant.nom} {etudiant.prenom}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}